create table if not exists public.line_notification_settings(church_id text not null check(church_id in ('M+','SHiNE')),event_key text not null check(event_key in ('binding_review','newcomer_care_reminders')),enabled boolean not null default true,recipient_staff_ids uuid[] not null default '{}',group_id text not null default '',updated_at timestamptz not null default now(),primary key(church_id,event_key));
alter table public.line_notification_settings enable row level security; revoke all on public.line_notification_settings from public,anon,authenticated; grant all on public.line_notification_settings to service_role;
insert into public.line_notification_settings(church_id,event_key,recipient_staff_ids) select church,event,coalesce((select array_agg(id order by display_name) from public.pastoral_staff where is_active and display_name in ('吳俊璋牧師','謝碧鳳師母')),'{}'::uuid[]) from unnest(array['M+','SHiNE']) church cross join unnest(array['binding_review','newcomer_care_reminders']) event on conflict do nothing;
create or replace function public.get_line_notification_settings(p_church text) returns jsonb language plpgsql security definer set search_path='' as $$ begin perform church_auth.lock_binding_reviewer(p_church); return jsonb_build_object('staff',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',display_name,'role',role,'has_line',line_subject is not null) order by display_name),'[]'::jsonb) from public.pastoral_staff where is_active),'rules',(select coalesce(jsonb_agg(jsonb_build_object('event_key',event_key,'enabled',enabled,'recipient_staff_ids',recipient_staff_ids,'group_id',group_id) order by event_key),'[]'::jsonb) from public.line_notification_settings where church_id=p_church)); end $$;
create or replace function public.save_line_notification_setting(p_church text,p_event_key text,p_enabled boolean,p_recipient_staff_ids uuid[],p_group_id text) returns boolean language plpgsql security definer set search_path='' as $$ begin perform church_auth.lock_binding_reviewer(p_church); if p_event_key not in ('binding_review','newcomer_care_reminders') or cardinality(p_recipient_staff_ids)>20 or length(coalesce(p_group_id,''))>80 then raise exception 'invalid_input'; end if; if exists(select 1 from unnest(p_recipient_staff_ids) x(id) where not exists(select 1 from public.pastoral_staff s where s.id=x.id and s.is_active)) then raise exception 'invalid_staff'; end if; if coalesce(p_group_id,'')<>'' and coalesce(p_group_id,'') !~ '^C[0-9a-fA-F]{32}$' then raise exception 'invalid_group'; end if; insert into public.line_notification_settings(church_id,event_key,enabled,recipient_staff_ids,group_id,updated_at) values(p_church,p_event_key,p_enabled,coalesce(p_recipient_staff_ids,'{}'),coalesce(p_group_id,''),now()) on conflict(church_id,event_key) do update set enabled=excluded.enabled,recipient_staff_ids=excluded.recipient_staff_ids,group_id=excluded.group_id,updated_at=now(); return true; end $$;
revoke all on function public.get_line_notification_settings(text),public.save_line_notification_setting(text,text,boolean,uuid[],text) from public,anon; grant execute on function public.get_line_notification_settings(text),public.save_line_notification_setting(text,text,boolean,uuid[],text) to authenticated,service_role;
